package com.herbwise;

import com.herbwise.models.PriceCalculationMode;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

/**
 * RuneLite configuration interface for HerbWise.
 * All settings persist between RuneLite sessions via RuneLite's ConfigManager.
 */
@ConfigGroup(HerbWiseConfig.CONFIG_GROUP)
public interface HerbWiseConfig extends Config
{
	String CONFIG_GROUP = "herbwise";

	enum TableDisplayMode
	{
		DETAILED("Detailed Table"),
		COMPACT("Compact Table");

		private final String label;

		TableDisplayMode(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	enum HerbloreBoostMode
	{
		NONE("No Boost (+0)", 0),
		BOTANICAL_PIE("Botanical Pie (+4)", 4),
		SPICY_STEW("Spicy Stew (+5 Max)", 5);

		private final String label;
		private final int boostLevels;

		HerbloreBoostMode(String label, int boostLevels)
		{
			this.label = label;
			this.boostLevels = boostLevels;
		}

		public int getBoostLevels()
		{
			return boostLevels;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigSection(
		name = "Price & Market Settings",
		description = "Configure OSRS Wiki Real-Time Prices API polling, price calculation mode, and Grand Exchange tax.",
		position = 0
	)
	String SECTION_PRICES = "prices";

	@ConfigSection(
		name = "Filtering & Display",
		description = "Configure default dashboard filters, table density, and XP/hr display.",
		position = 1
	)
	String SECTION_DISPLAY = "display";

	@ConfigSection(
		name = "Planner Defaults",
		description = "Configure default GP budget, target Herblore level, skill boost, and notifications.",
		position = 2
	)
	String SECTION_DEFAULTS = "defaults";

	@Range(min = 30, max = 3600)
	@ConfigItem(
		keyName = "priceRefreshIntervalSeconds",
		name = "Price refresh interval (s)",
		description = "Background refresh interval in seconds for fetching OSRS Wiki prices (30 to 3600s).",
		section = SECTION_PRICES,
		position = 1
	)
	default int priceRefreshIntervalSeconds()
	{
		return 60;
	}

	@ConfigItem(
		keyName = "priceCalculationMode",
		name = "Price calculation mode",
		description = "Select how ingredient buying prices and finished potion selling prices are calculated.",
		section = SECTION_PRICES,
		position = 2
	)
	default PriceCalculationMode priceCalculationMode()
	{
		return PriceCalculationMode.INSTANT_CONSERVATIVE;
	}

	@ConfigItem(
		keyName = "includeGeTax",
		name = "Include Grand Exchange tax",
		description = "Deduct the 2% OSRS Grand Exchange seller tax (capped at 5M GP, 0 GP under 50 GP) from finished potion sales.",
		section = SECTION_PRICES,
		position = 3
	)
	default boolean includeGeTax()
	{
		return true;
	}

	@ConfigItem(
		keyName = "enableVolatilityWarnings",
		name = "Enable price volatility warnings",
		description = "Warn when an ingredient or potion has a wide instant buy/sell spread or sharp 5m vs 1h swing.",
		section = SECTION_PRICES,
		position = 4
	)
	default boolean enableVolatilityWarnings()
	{
		return true;
	}

	@ConfigItem(
		keyName = "enableStalePriceWarnings",
		name = "Enable stale price warnings",
		description = "Warn when an item's most recent Grand Exchange trade timestamp is older than 3 hours or from cache.",
		section = SECTION_PRICES,
		position = 5
	)
	default boolean enableStalePriceWarnings()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showProfitableOnly",
		name = "Show profitable recipes only",
		description = "Filter the main recommendations table to show only profitable potions by default.",
		section = SECTION_DISPLAY,
		position = 6
	)
	default boolean showProfitableOnly()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showAvailableAtLevelOnly",
		name = "Show available at current level only",
		description = "Only display potions that your current Herblore level (plus active boost) can make.",
		section = SECTION_DISPLAY,
		position = 7
	)
	default boolean showAvailableAtLevelOnly()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showXpPerHourEstimates",
		name = "Show XP per hour estimates",
		description = "Display estimated Herblore XP/hr and GP/hr rates across tables and recommendation cards.",
		section = SECTION_DISPLAY,
		position = 8
	)
	default boolean showXpPerHourEstimates()
	{
		return true;
	}

	@ConfigItem(
		keyName = "tableDisplayMode",
		name = "Table display mode",
		description = "Switch between a detailed multi-metric view and a compact single-line table.",
		section = SECTION_DISPLAY,
		position = 9
	)
	default TableDisplayMode tableDisplayMode()
	{
		return TableDisplayMode.DETAILED;
	}

	@Range(min = 1000, max = 2147483647)
	@ConfigItem(
		keyName = "defaultBudgetGp",
		name = "Default budget (GP)",
		description = "Default Grand Exchange GP budget used in the Budget Calculator and affordability checks.",
		section = SECTION_DEFAULTS,
		position = 10
	)
	default int defaultBudgetGp()
	{
		return 1_000_000;
	}

	@Range(min = 2, max = 99)
	@ConfigItem(
		keyName = "defaultTargetLevel",
		name = "Default target level",
		description = "Default target Herblore level (2..99) in the Production & XP Calculator.",
		section = SECTION_DEFAULTS,
		position = 11
	)
	default int defaultTargetLevel()
	{
		return 90;
	}

	@ConfigItem(
		keyName = "herbloreBoostMode",
		name = "Supported Herblore boost",
		description = "Optional temporary Herblore boost (Botanical pie +4 or Spicy stew +5) applied to level unlock checks.",
		section = SECTION_DEFAULTS,
		position = 12
	)
	default HerbloreBoostMode herbloreBoostMode()
	{
		return HerbloreBoostMode.NONE;
	}

	@ConfigItem(
		keyName = "enableNotifications",
		name = "Enable notifications",
		description = "Send a RuneLite notification when a high-profit potion opportunity is detected on refresh.",
		section = SECTION_DEFAULTS,
		position = 13
	)
	default boolean enableNotifications()
	{
		return false;
	}
}

package com.herbwise;

import com.herbwise.models.PotionProfitResult;
import com.herbwise.services.HerbloreDataService;
import com.herbwise.services.HerbloreDataService.ConnectionState;
import com.herbwise.ui.HerbWiseBudgetPanel;
import com.herbwise.ui.HerbWiseDashboard;
import com.herbwise.ui.HerbWiseMarketPanel;
import com.herbwise.ui.HerbWisePotionTable;
import com.herbwise.ui.HerbWiseRecipeDetailPanel;
import com.herbwise.ui.HerbWiseSettingsPanel;
import com.herbwise.ui.HerbWiseTheme;
import com.herbwise.ui.HerbWiseTheme.HerbButton;
import com.herbwise.ui.HerbWiseXpCalculator;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Dimension;
import java.awt.GridLayout;
import javax.inject.Inject;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.PluginPanel;

/**
 * Main RuneLite sidebar panel for HerbWise.
 * Organizes the 6 required tabs (Dashboard, Potion Database, Budget Calculator,
 * XP Calculator, Market Analysis, and Settings) plus the interactive Recipe Detail View.
 */
public class HerbWisePanel extends PluginPanel
{
	public static final String TAB_DASHBOARD = "DASHBOARD";
	public static final String TAB_DATABASE = "DATABASE";
	public static final String TAB_BUDGET = "BUDGET";
	public static final String TAB_XP_CALC = "XP_CALC";
	public static final String TAB_MARKET = "MARKET";
	public static final String TAB_SETTINGS = "SETTINGS";
	public static final String TAB_RECIPE_DETAIL = "RECIPE_DETAIL";

	public static final int DEFAULT_WIDE_PANEL_WIDTH = 580;
	public static final int DEFAULT_WIDE_PANEL_HEIGHT = 820;

	private final HerbloreDataService dataService;
	private javax.swing.JFrame popoutFrame;

	// Header status widgets
	private final JLabel statusBadgeLabel;
	private final JLabel lastUpdatedLabel;
	private final HerbButton manualRefreshButton;

	// Navigation buttons
	private final HerbButton btnDashboard;
	private final HerbButton btnDatabase;
	private final HerbButton btnBudget;
	private final HerbButton btnXpCalc;
	private final HerbButton btnMarket;
	private final HerbButton btnSettings;

	// Card layout & child tabs
	private final CardLayout cardLayout;
	private final JPanel cardContainer;
	private final HerbWiseDashboard dashboardPanel;
	private final JPanel databaseTabWrapper;
	private final HerbWisePotionTable databaseTable;
	private final HerbWiseBudgetPanel budgetPanel;
	private final HerbWiseXpCalculator xpCalculatorPanel;
	private final HerbWiseMarketPanel marketPanel;
	private final HerbWiseSettingsPanel settingsPanel;
	private final HerbWiseRecipeDetailPanel recipeDetailPanel;

	private String currentActiveTab = TAB_DASHBOARD;
	private String previousTabBeforeDetail = TAB_DASHBOARD;

	@Inject
	public HerbWisePanel(HerbloreDataService dataService)
	{
		super(false);
		this.dataService = dataService;

		setLayout(new BorderLayout(0, 0));
		setBackground(HerbWiseTheme.BG_MATTE_BLACK);
		setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));

		// ====================================================================
		// TOP HEADER & NAVIGATION BAR
		// ====================================================================
		JPanel topContainer = new JPanel();
		topContainer.setLayout(new BoxLayout(topContainer, BoxLayout.Y_AXIS));
		topContainer.setBackground(HerbWiseTheme.BG_MATTE_BLACK);
		topContainer.setBorder(BorderFactory.createEmptyBorder(0, 0, 5, 0));

		// Brand & API Status Card
		JPanel headerCard = new JPanel();
		headerCard.setLayout(new BoxLayout(headerCard, BoxLayout.Y_AXIS));
		headerCard.setBackground(HerbWiseTheme.BG_DEEP_CHARCOAL);
		headerCard.setBorder(HerbWiseTheme.CARD_BORDER_ACCENT);

		JPanel titleRow = new JPanel(new BorderLayout(6, 0));
		titleRow.setOpaque(false);

		JPanel brandLeft = new JPanel(new BorderLayout(6, 0));
		brandLeft.setOpaque(false);
		JLabel iconLabel = new JLabel(new ImageIcon(HerbWiseTheme.createHeaderIcon()));
		brandLeft.add(iconLabel, BorderLayout.WEST);

		JPanel titleTextCol = new JPanel(new GridLayout(2, 1, 0, 0));
		titleTextCol.setOpaque(false);
		JLabel titleLbl = new JLabel("HERBWISE");
		titleLbl.setFont(HerbWiseTheme.getTitleFont());
		titleLbl.setForeground(HerbWiseTheme.ACCENT_HERB_BRIGHT);
		JLabel subLbl = new JLabel("Herblore Profit & XP Assistant");
		subLbl.setFont(HerbWiseTheme.getSmallFont());
		subLbl.setForeground(HerbWiseTheme.TEXT_MUTED);
		titleTextCol.add(titleLbl);
		titleTextCol.add(subLbl);
		brandLeft.add(titleTextCol, BorderLayout.CENTER);
		titleRow.add(brandLeft, BorderLayout.CENTER);

		manualRefreshButton = new HerbButton("↻ Refresh");
		manualRefreshButton.setToolTipText("Fetch latest real-time OSRS Wiki prices now");
		manualRefreshButton.addActionListener(e -> {
			if (dataService != null)
			{
				dataService.refreshPricesAsync();
			}
		});

		HerbButton widePopoutBtn = new HerbButton("⤢ Pop Out", true);
		widePopoutBtn.setToolTipText("Open HerbWise in a standalone resizable window");
		widePopoutBtn.addActionListener(e -> openWidePopoutWindow());

		JPanel headerActions = new JPanel(new GridLayout(1, 2, 4, 0));
		headerActions.setOpaque(false);
		headerActions.add(widePopoutBtn);
		headerActions.add(manualRefreshButton);

		titleRow.add(headerActions, BorderLayout.EAST);
		headerCard.add(titleRow);
		headerCard.add(Box.createRigidArea(new Dimension(0, 5)));

		// API Connection Status & Last Updated Row (Section 2)
		JPanel statusRow = new JPanel(new BorderLayout(4, 0));
		statusRow.setOpaque(false);

		statusBadgeLabel = new JLabel("● LIVE API");
		statusBadgeLabel.setFont(HerbWiseTheme.getBadgeFont());
		statusBadgeLabel.setForeground(HerbWiseTheme.COLOR_PROFIT_GREEN);
		statusRow.add(statusBadgeLabel, BorderLayout.WEST);

		lastUpdatedLabel = new JLabel("Updated: Just now");
		lastUpdatedLabel.setFont(HerbWiseTheme.getSmallFont());
		lastUpdatedLabel.setForeground(HerbWiseTheme.TEXT_SECONDARY);
		lastUpdatedLabel.setHorizontalAlignment(SwingConstants.RIGHT);
		statusRow.add(lastUpdatedLabel, BorderLayout.CENTER);
		headerCard.add(statusRow);

		topContainer.add(headerCard);
		topContainer.add(Box.createRigidArea(new Dimension(0, 5)));

		// 6 Navigation Tabs arranged in a compact 2x3 grid
		JPanel navGrid = new JPanel(new GridLayout(2, 3, 4, 4));
		navGrid.setOpaque(false);

		btnDashboard = new HerbButton("1. Dashboard");
		btnDatabase = new HerbButton("2. Database");
		btnBudget = new HerbButton("3. Budget");
		btnXpCalc = new HerbButton("4. XP Calc");
		btnMarket = new HerbButton("5. Market");
		btnSettings = new HerbButton("6. Settings");

		btnDashboard.addActionListener(e -> switchTab(TAB_DASHBOARD));
		btnDatabase.addActionListener(e -> switchTab(TAB_DATABASE));
		btnBudget.addActionListener(e -> switchTab(TAB_BUDGET));
		btnXpCalc.addActionListener(e -> switchTab(TAB_XP_CALC));
		btnMarket.addActionListener(e -> switchTab(TAB_MARKET));
		btnSettings.addActionListener(e -> switchTab(TAB_SETTINGS));

		navGrid.add(btnDashboard);
		navGrid.add(btnDatabase);
		navGrid.add(btnBudget);
		navGrid.add(btnXpCalc);
		navGrid.add(btnMarket);
		navGrid.add(btnSettings);

		topContainer.add(navGrid);
		add(topContainer, BorderLayout.NORTH);

		// ====================================================================
		// TAB CONTENT CARDS
		// ====================================================================
		cardLayout = new CardLayout();
		cardContainer = new JPanel(cardLayout);
		cardContainer.setBackground(HerbWiseTheme.BG_MATTE_BLACK);

		dashboardPanel = new HerbWiseDashboard(dataService, this::openRecipeDetail);

		// Dedicated Potion Database Tab (includes 1-4 dose variants & alt recipes by default)
		databaseTabWrapper = new JPanel(new BorderLayout(0, 4));
		databaseTabWrapper.setBackground(HerbWiseTheme.BG_MATTE_BLACK);
		databaseTabWrapper.setBorder(BorderFactory.createEmptyBorder(4, 2, 4, 2));
		JLabel dbHeader = HerbWiseTheme.createSectionHeader("Complete Verified Herblore Recipe Database");
		databaseTabWrapper.add(dbHeader, BorderLayout.NORTH);
		databaseTable = new HerbWisePotionTable(dataService, this::openRecipeDetail, true);
		databaseTabWrapper.add(databaseTable, BorderLayout.CENTER);

		budgetPanel = new HerbWiseBudgetPanel(dataService);
		xpCalculatorPanel = new HerbWiseXpCalculator(dataService);
		marketPanel = new HerbWiseMarketPanel(dataService);
		settingsPanel = new HerbWiseSettingsPanel(dataService);
		recipeDetailPanel = new HerbWiseRecipeDetailPanel(
			dataService,
			() -> switchTab(previousTabBeforeDetail),
			result -> {
				budgetPanel.selectPotion(result);
				switchTab(TAB_BUDGET);
			},
			result -> {
				xpCalculatorPanel.selectPotion(result);
				switchTab(TAB_XP_CALC);
			},
			itemId -> {
				marketPanel.selectItem(itemId);
				switchTab(TAB_MARKET);
			}
		);

		cardContainer.add(dashboardPanel, TAB_DASHBOARD);
		cardContainer.add(databaseTabWrapper, TAB_DATABASE);
		cardContainer.add(budgetPanel, TAB_BUDGET);
		cardContainer.add(xpCalculatorPanel, TAB_XP_CALC);
		cardContainer.add(marketPanel, TAB_MARKET);
		cardContainer.add(settingsPanel, TAB_SETTINGS);
		cardContainer.add(recipeDetailPanel, TAB_RECIPE_DETAIL);

		add(cardContainer, BorderLayout.CENTER);

		if (this.dataService != null)
		{
			this.dataService.addUiUpdateListener(this::refreshAllTabs);
		}

		switchTab(TAB_DASHBOARD);
		refreshHeaderStatus();
		HerbWiseTheme.normalizeBoxAlignment(this);
	}

	public void switchTab(String tabKey)
	{
		if (tabKey == null)
		{
			return;
		}
		if (!TAB_RECIPE_DETAIL.equals(tabKey))
		{
			this.previousTabBeforeDetail = tabKey;
		}
		this.currentActiveTab = tabKey;

		btnDashboard.setActive(TAB_DASHBOARD.equals(tabKey));
		btnDatabase.setActive(TAB_DATABASE.equals(tabKey));
		btnBudget.setActive(TAB_BUDGET.equals(tabKey));
		btnXpCalc.setActive(TAB_XP_CALC.equals(tabKey));
		btnMarket.setActive(TAB_MARKET.equals(tabKey));
		btnSettings.setActive(TAB_SETTINGS.equals(tabKey));

		cardLayout.show(cardContainer, tabKey);
		HerbWiseTheme.normalizeBoxAlignment(this);
		revalidate();
		repaint();
	}

	public void openRecipeDetail(PotionProfitResult result)
	{
		if (result == null)
		{
			return;
		}
		recipeDetailPanel.displayRecipe(result);
		switchTab(TAB_RECIPE_DETAIL);
	}

	public void refreshAllTabs()
	{
		refreshHeaderStatus();
		dashboardPanel.refresh();
		databaseTable.refreshTable();
		budgetPanel.refresh();
		xpCalculatorPanel.refresh();
		marketPanel.refresh();
		settingsPanel.refreshFromService();
		recipeDetailPanel.render();
		revalidate();
		repaint();
	}

	private void refreshHeaderStatus()
	{
		if (dataService == null)
		{
			return;
		}
		ConnectionState state = dataService.getConnectionState();
		statusBadgeLabel.setText("● " + state.getBadgeText());
		statusBadgeLabel.setForeground(state.getBadgeColor());
		statusBadgeLabel.setToolTipText(dataService.getStatusDetailText());

		lastUpdatedLabel.setText("Updated: " + dataService.getFormattedLastUpdated());
		manualRefreshButton.setEnabled(!dataService.isRefreshRunning());
		manualRefreshButton.setText(dataService.isRefreshRunning() ? "Fetching..." : "↻ Refresh");
	}

	/**
	 * Overrides RuneLite's default 225px PluginPanel width so HerbWise renders at a compact
	 * yet fully readable 520px width where all 10 columns and cards fit cleanly without hogging the screen.
	 */
	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(DEFAULT_WIDE_PANEL_WIDTH, DEFAULT_WIDE_PANEL_HEIGHT);
	}

	@Override
	public Dimension getMinimumSize()
	{
		return new Dimension(320, 560);
	}

	public void openWidePopoutWindow()
	{
		if (popoutFrame != null && popoutFrame.isDisplayable())
		{
			popoutFrame.setVisible(true);
			popoutFrame.toFront();
			popoutFrame.requestFocus();
			return;
		}
		HerbWisePanel widePanel = new HerbWisePanel(dataService);
		popoutFrame = new javax.swing.JFrame("HerbWise — OSRS Herblore Profit & Training Assistant");
		popoutFrame.setDefaultCloseOperation(javax.swing.WindowConstants.DISPOSE_ON_CLOSE);
		popoutFrame.setIconImage(HerbWiseTheme.createHeaderIcon());
		popoutFrame.getContentPane().setBackground(HerbWiseTheme.BG_MATTE_BLACK);
		popoutFrame.getContentPane().setLayout(new BorderLayout());
		popoutFrame.getContentPane().add(widePanel, BorderLayout.CENTER);
		popoutFrame.setSize(new Dimension(600, 860));
		popoutFrame.setMinimumSize(new Dimension(480, 620));
		popoutFrame.setLocationRelativeTo(this);
		popoutFrame.setVisible(true);
	}

	public String getCurrentActiveTab() { return currentActiveTab; }
	public HerbWiseDashboard getDashboardPanel() { return dashboardPanel; }
	public HerbWisePotionTable getDatabaseTable() { return databaseTable; }
	public HerbWiseBudgetPanel getBudgetPanel() { return budgetPanel; }
	public HerbWiseXpCalculator getXpCalculatorPanel() { return xpCalculatorPanel; }
	public HerbWiseMarketPanel getMarketPanel() { return marketPanel; }
	public HerbWiseSettingsPanel getSettingsPanel() { return settingsPanel; }
	public HerbWiseRecipeDetailPanel getRecipeDetailPanel() { return recipeDetailPanel; }
}

package com.herbwise;

import com.google.inject.Provides;
import com.herbwise.services.HerbloreDataService;
import com.herbwise.services.PlayerSkillService;
import com.herbwise.ui.HerbWiseTheme;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Main RuneLite plugin entry point for HerbWise — OSRS Herblore Profit & Training Assistant.
 */
@PluginDescriptor(
	name = "HerbWise",
	description = "OSRS Herblore Profit & Training Assistant — real-time GE potion profit, XP/hr, budget & recipe calculator",
	tags = {
		"herblore",
		"potion",
		"profit",
		"calculator",
		"grand exchange",
		"training",
		"herbwise",
		"skilling"
	}
)
public class HerbWisePlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(HerbWisePlugin.class);

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private HerbWiseConfig config;

	@Inject
	private HerbloreDataService dataService;

	@Inject
	private PlayerSkillService playerSkillService;

	private HerbWisePanel panel;
	private NavigationButton navButton;

	@Provides
	HerbWiseConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(HerbWiseConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		log.info("[HerbWise] Starting OSRS Herblore Profit & Training Assistant...");
		dataService.syncSettingsFromConfig();
		dataService.startUp();

		panel = new HerbWisePanel(dataService);
		BufferedImage icon = HerbWiseTheme.createToolbarIcon();

		navButton = NavigationButton.builder()
			.tooltip("HerbWise — Herblore Profit & Training Assistant")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();

		if (clientToolbar != null)
		{
			clientToolbar.addNavigation(navButton);
		}
	}

	@Override
	protected void shutDown() throws Exception
	{
		log.info("[HerbWise] Shutting down HerbWise plugin...");
		if (clientToolbar != null && navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		if (dataService != null)
		{
			dataService.shutDown();
		}
		panel = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (playerSkillService != null)
		{
			playerSkillService.refreshFromClient();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (playerSkillService != null)
		{
			playerSkillService.refreshFromClient();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (playerSkillService != null)
		{
			playerSkillService.refreshFromClient();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event == null || !HerbWiseConfig.CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}
		if (dataService != null)
		{
			dataService.syncSettingsFromConfig();
			dataService.recalculateAll(java.time.Instant.now().getEpochSecond());
			if (panel != null)
			{
				SwingUtilities.invokeLater(panel::refreshAllTabs);
			}
		}
	}

	public HerbWisePanel getPanel()
	{
		return panel;
	}

	public HerbloreDataService getDataService()
	{
		return dataService;
	}
}

package com.herbwise.calculators;

import com.herbwise.models.BudgetCalculationResult;
import com.herbwise.models.PotionIngredient;
import com.herbwise.models.PotionProfitResult;
import com.herbwise.models.PotionRecipe;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Dedicated GP budget and quantity planning calculator for HerbWise.
 * Computes maximum affordable potions, total ingredient costs, expected sale values,
 * net profit/loss, total XP gained, remaining GP, and inventory loads required.
 */
@Singleton
public class BudgetCalculator
{
	public static final long[] BUDGET_PRESETS_GP = new long[]{
		100_000L,
		500_000L,
		1_000_000L,
		5_000_000L,
		10_000_000L,
		25_000_000L
	};

	private final ProductionTimeCalculator productionTimeCalculator;

	@Inject
	public BudgetCalculator(ProductionTimeCalculator productionTimeCalculator)
	{
		this.productionTimeCalculator = productionTimeCalculator != null
			? productionTimeCalculator
			: new ProductionTimeCalculator();
	}

	public BudgetCalculator()
	{
		this(new ProductionTimeCalculator());
	}

	/**
	 * Calculates how many potions the player can produce within {@code budgetGp} based on initial ingredient investment.
	 */
	public BudgetCalculationResult calculateBudget(long budgetGp, PotionProfitResult potionResult)
	{
		long safeBudget = Math.max(0L, budgetGp);
		if (potionResult == null || potionResult.getRecipe() == null || !potionResult.isHasIngredientPriceData())
		{
			return new BudgetCalculationResult(
				safeBudget, potionResult, 0L, 0L, 0L, 0L, 0L, 0L, 0.0, safeBudget, 14, 0L, 0.0, null
			);
		}

		long costPerPotion = potionResult.getTotalIngredientCost();
		if (costPerPotion <= 0L)
		{
			return new BudgetCalculationResult(
				safeBudget, potionResult, 0L, 0L, 0L, 0L, 0L, 0L, 0.0, safeBudget, 14, 0L, 0.0, null
			);
		}

		long maxPotions = safeBudget / costPerPotion;
		return buildForQuantity(safeBudget, maxPotions, potionResult);
	}

	/**
	 * Calculates exact costs, ingredients, and XP for a specific quantity of potions compared against {@code budgetGp}.
	 */
	public BudgetCalculationResult buildForQuantity(long budgetGp, long quantity, PotionProfitResult potionResult)
	{
		long safeBudget = Math.max(0L, budgetGp);
		long safeQty = Math.max(0L, quantity);
		if (potionResult == null || potionResult.getRecipe() == null)
		{
			return new BudgetCalculationResult(
				safeBudget, null, 0L, 0L, 0L, 0L, 0L, 0L, 0.0, safeBudget, 14, 0L, 0.0, null
			);
		}

		PotionRecipe recipe = potionResult.getRecipe();
		long totalIngredientCost = safeMultiply(potionResult.getTotalIngredientCost(), safeQty);
		long expectedGrossSale = potionResult.isHasCompletePriceData()
			? safeMultiply(potionResult.getFinishedPotionSalePrice(), safeQty)
			: 0L;
		long expectedGeTax = potionResult.isHasCompletePriceData()
			? safeMultiply(potionResult.getGeTax(), safeQty)
			: 0L;
		long expectedNetSale = potionResult.isHasCompletePriceData()
			? safeMultiply(potionResult.getNetSaleValue(), safeQty)
			: 0L;
		long expectedProfitLoss = potionResult.isHasCompletePriceData()
			? safeMultiply(potionResult.getNetProfitPerPotion(), safeQty)
			: -totalIngredientCost;

		double totalXp = safeQty * potionResult.getXpPerPotion();
		long remainingGp = Math.max(0L, safeBudget - totalIngredientCost);

		int perLoad = productionTimeCalculator.getPotionsPerInventoryLoad(recipe);
		long loads = productionTimeCalculator.calculateInventoryLoads(recipe, safeQty);
		double minutes = productionTimeCalculator.calculateMinutesRequired(recipe, safeQty);

		Map<PotionIngredient, Long> shoppingList = new LinkedHashMap<>();
		for (PotionIngredient ing : recipe.getIngredients())
		{
			shoppingList.put(ing, safeMultiply(safeQty, ing.getQuantity()));
		}

		return new BudgetCalculationResult(
			safeBudget,
			potionResult,
			safeQty,
			totalIngredientCost,
			expectedGrossSale,
			expectedGeTax,
			expectedNetSale,
			expectedProfitLoss,
			totalXp,
			remainingGp,
			perLoad,
			loads,
			minutes,
			shoppingList
		);
	}

	/**
	 * Recommends the best potion to make within {@code budgetGp} at {@code playerLevel}.
	 */
	public Optional<PotionProfitResult> recommendBestPotionForBudget(
		long budgetGp,
		int playerLevel,
		List<PotionProfitResult> results)
	{
		if (results == null || results.isEmpty() || budgetGp <= 0L)
		{
			return Optional.empty();
		}

		return results.stream()
			.filter(r -> r != null && r.getRecipe() != null)
			.filter(r -> !r.getRecipe().isUnfinishedPotionRecipe())
			.filter(r -> !r.getRecipe().isAlternativeRecipe())
			.filter(PotionProfitResult::isHasCompletePriceData)
			.filter(r -> r.getXpPerPotion() > 10.0)
			.filter(r -> r.getRecipe().getRequiredLevel() <= Math.max(1, playerLevel))
			.filter(r -> r.getTotalIngredientCost() > 0L && r.getTotalIngredientCost() <= budgetGp)
			.max(Comparator.comparingDouble(r -> scoreForBudget(r, budgetGp)));
	}

	private double scoreForBudget(PotionProfitResult r, long budgetGp)
	{
		long affordableCount = budgetGp / Math.max(1L, r.getTotalIngredientCost());
		if (affordableCount <= 0L)
		{
			return -1_000_000.0;
		}
		double baseScore = r.getOverallTrainingScore();
		// Prefer recipes where the player can afford at least a full inventory (14+ potions)
		double batchBonus = Math.min(20.0, Math.log10(affordableCount + 1.0) * 6.5);
		return baseScore + batchBonus;
	}

	private static long safeMultiply(long a, long b)
	{
		try
		{
			return Math.multiplyExact(a, b);
		}
		catch (ArithmeticException ex)
		{
			return (a > 0 && b > 0) || (a < 0 && b < 0) ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}
}

package com.herbwise.calculators;

import com.herbwise.data.GeTaxRules;
import javax.inject.Singleton;

/**
 * Dedicated Grand Exchange tax calculation engine implementing official OSRS GE tax rules:
 * - 2% tax on eligible finished item sales, rounded down per individual item.
 * - 0 GP tax on items selling for under 50 GP.
 * - 5,000,000 GP maximum tax cap per individual item (sales >= 250,000,000 GP).
 * - 0 GP tax on explicitly exempt or untradeable items.
 * - 0 GP tax on all ingredient purchases (buyer never pays GE tax).
 */
@Singleton
public class GeTaxCalculator
{
	/**
	 * Calculates the Grand Exchange tax deducted per single item sold.
	 */
	public long calculateTaxPerItem(int itemId, long salePricePerItem, boolean includeTax)
	{
		if (!includeTax || salePricePerItem < GeTaxRules.MIN_TAXABLE_PRICE_GP)
		{
			return 0L;
		}
		if (GeTaxRules.isItemTaxExempt(itemId))
		{
			return 0L;
		}
		long rawTax = salePricePerItem / GeTaxRules.TAX_DIVISOR;
		return Math.min(GeTaxRules.MAX_TAX_PER_ITEM_GP, rawTax);
	}

	/**
	 * Calculates the total Grand Exchange tax for selling {@code quantity} of an item.
	 * Per OSRS mechanics, tax is rounded down per individual item first, then multiplied by quantity.
	 */
	public long calculateTotalTax(int itemId, long salePricePerItem, long quantity, boolean includeTax)
	{
		if (quantity <= 0L)
		{
			return 0L;
		}
		long taxPerItem = calculateTaxPerItem(itemId, salePricePerItem, includeTax);
		if (taxPerItem <= 0L)
		{
			return 0L;
		}
		return Math.multiplyExact(taxPerItem, quantity);
	}

	/**
	 * Calculates the net GP received per item after deducting applicable Grand Exchange tax.
	 */
	public long calculateNetSalePricePerItem(int itemId, long grossSalePricePerItem, boolean includeTax)
	{
		if (grossSalePricePerItem <= 0L)
		{
			return 0L;
		}
		long tax = calculateTaxPerItem(itemId, grossSalePricePerItem, includeTax);
		return Math.max(0L, grossSalePricePerItem - tax);
	}

	/**
	 * Buying ingredients on the Grand Exchange never incurs tax for the buyer.
	 */
	public long calculateIngredientPurchaseTax(int itemId, long purchasePrice)
	{
		return 0L;
	}
}

package com.herbwise.calculators;

import com.herbwise.data.HerbloreXpTable;
import com.herbwise.models.PotionIngredient;
import com.herbwise.models.PotionProfitResult;
import com.herbwise.models.PotionRecipe;
import com.herbwise.models.XpProductionPlan;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Calculates exact Herblore experience requirements, potions required to reach target levels or XP goals,
 * total ingredient shopping lists, total GP investment, expected return after GE tax, and production time.
 */
@Singleton
public class HerbloreXpCalculator
{
	private final ProductionTimeCalculator productionTimeCalculator;

	@Inject
	public HerbloreXpCalculator(ProductionTimeCalculator productionTimeCalculator)
	{
		this.productionTimeCalculator = productionTimeCalculator != null
			? productionTimeCalculator
			: new ProductionTimeCalculator();
	}

	public HerbloreXpCalculator()
	{
		this(new ProductionTimeCalculator());
	}

	/**
	 * Calculates a full production plan between a starting XP amount and a target XP amount.
	 */
	public XpProductionPlan calculateByXpGoal(
		long currentXp,
		long targetXp,
		PotionProfitResult potionResult)
	{
		long safeCurrentXp = Math.max(0L, Math.min(HerbloreXpTable.MAX_XP, currentXp));
		long safeTargetXp = Math.max(safeCurrentXp, Math.min(HerbloreXpTable.MAX_XP, targetXp));
		long xpRequired = Math.max(0L, safeTargetXp - safeCurrentXp);

		int currentLevel = HerbloreXpTable.getLevelForXp(safeCurrentXp);
		int targetLevel = HerbloreXpTable.getLevelForXp(safeTargetXp);

		if (potionResult == null || potionResult.getRecipe() == null || potionResult.getXpPerPotion() <= 0.0)
		{
			return new XpProductionPlan(
				currentLevel, targetLevel, safeCurrentXp, safeTargetXp,
				xpRequired, 0L, 0.0, potionResult,
				0L, 0L, 0L, 0L, 0L, 0.0, 0.0, 0.0, 0L, null
			);
		}

		double xpPerPotion = potionResult.getXpPerPotion();
		long potionsNeeded = xpRequired > 0L
			? (long) Math.ceil((double) xpRequired / xpPerPotion)
			: 0L;

		return buildPlanForPotionQuantity(
			currentLevel,
			targetLevel,
			safeCurrentXp,
			safeTargetXp,
			xpRequired,
			potionsNeeded,
			potionResult
		);
	}

	/**
	 * Calculates a full production plan from a starting Herblore level to a target Herblore level.
	 */
	public XpProductionPlan calculateByLevels(
		int currentLevel,
		int targetLevel,
		PotionProfitResult potionResult)
	{
		int safeStartLevel = Math.max(1, Math.min(HerbloreXpTable.MAX_SKILL_LEVEL, currentLevel));
		int safeTargetLevel = Math.max(safeStartLevel, Math.min(HerbloreXpTable.MAX_SKILL_LEVEL, targetLevel));
		long startXp = HerbloreXpTable.getXpForLevel(safeStartLevel);
		long endXp = HerbloreXpTable.getXpForLevel(safeTargetLevel);
		return calculateByXpGoal(startXp, endXp, potionResult);
	}

	/**
	 * Calculates a production plan for a specific desired XP gain (e.g. +10,000 XP).
	 */
	public XpProductionPlan calculateForDesiredXpGain(
		long currentXp,
		long desiredXpGain,
		PotionProfitResult potionResult)
	{
		long safeCurrent = Math.max(0L, currentXp);
		long safeGain = Math.max(0L, desiredXpGain);
		return calculateByXpGoal(safeCurrent, safeCurrent + safeGain, potionResult);
	}

	/**
	 * Calculates a production plan for an explicit custom quantity of potions.
	 */
	public XpProductionPlan calculateForPotionQuantity(
		long currentXp,
		long customPotionCount,
		PotionProfitResult potionResult)
	{
		long safeCurrentXp = Math.max(0L, currentXp);
		long safeCount = Math.max(0L, customPotionCount);
		int currentLevel = HerbloreXpTable.getLevelForXp(safeCurrentXp);

		if (potionResult == null || potionResult.getRecipe() == null)
		{
			return new XpProductionPlan(
				currentLevel, currentLevel, safeCurrentXp, safeCurrentXp,
				0L, 0L, 0.0, null,
				0L, 0L, 0L, 0L, 0L, 0.0, 0.0, 0.0, 0L, null
			);
		}

		double xpGained = safeCount * potionResult.getXpPerPotion();
		long resultingXp = Math.min(HerbloreXpTable.MAX_XP, safeCurrentXp + Math.round(xpGained));
		int resultingLevel = HerbloreXpTable.getLevelForXp(resultingXp);

		return buildPlanForPotionQuantity(
			currentLevel,
			resultingLevel,
			safeCurrentXp,
			resultingXp,
			Math.round(xpGained),
			safeCount,
			potionResult
		);
	}

	private XpProductionPlan buildPlanForPotionQuantity(
		int currentLevel,
		int targetLevel,
		long currentXp,
		long targetXp,
		long xpRequired,
		long potionsRequired,
		PotionProfitResult potionResult)
	{
		PotionRecipe recipe = potionResult.getRecipe();
		double totalXpGained = potionsRequired * potionResult.getXpPerPotion();

		Map<PotionIngredient, Long> shoppingList = new LinkedHashMap<>();
		for (PotionIngredient ing : recipe.getIngredients())
		{
			long totalIngQty = Math.multiplyExact(potionsRequired, (long) ing.getQuantity());
			shoppingList.put(ing, totalIngQty);
		}

		long totalInvestment = 0L;
		long expectedGrossSale = 0L;
		long expectedTax = 0L;
		long expectedNetSale = 0L;
		long totalProfitLoss = 0L;

		if (potionResult.isHasIngredientPriceData())
		{
			totalInvestment = safeMultiply(potionResult.getTotalIngredientCost(), potionsRequired);
		}
		if (potionResult.isHasCompletePriceData())
		{
			expectedGrossSale = safeMultiply(potionResult.getFinishedPotionSalePrice(), potionsRequired);
			expectedTax = safeMultiply(potionResult.getGeTax(), potionsRequired);
			expectedNetSale = safeMultiply(potionResult.getNetSaleValue(), potionsRequired);
			totalProfitLoss = safeMultiply(potionResult.getNetProfitPerPotion(), potionsRequired);
		}

		double netGpPerXp = totalXpGained > 0.0
			? ((double) totalProfitLoss / totalXpGained)
			: 0.0;

		double hours = productionTimeCalculator.calculateHoursRequired(recipe, potionsRequired);
		double minutes = hours * 60.0;
		long loads = productionTimeCalculator.calculateInventoryLoads(recipe, potionsRequired);

		return new XpProductionPlan(
			currentLevel,
			targetLevel,
			currentXp,
			targetXp,
			xpRequired,
			potionsRequired,
			totalXpGained,
			potionResult,
			totalInvestment,
			expectedGrossSale,
			expectedTax,
			expectedNetSale,
			totalProfitLoss,
			netGpPerXp,
			hours,
			minutes,
			loads,
			shoppingList
		);
	}

	private static long safeMultiply(long a, long b)
	{
		try
		{
			return Math.multiplyExact(a, b);
		}
		catch (ArithmeticException ex)
		{
			return (a > 0 && b > 0) || (a < 0 && b < 0) ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}
}

package com.herbwise.calculators;

import com.herbwise.models.ItemPrice;
import com.herbwise.models.PotionIngredient;
import com.herbwise.models.PotionProfitResult;
import com.herbwise.models.PotionProfitResult.PriceStatus;
import com.herbwise.models.PotionRecipe;
import com.herbwise.models.PriceCalculationMode;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Core profit, loss, and XP efficiency engine for HerbWise.
 * Evaluates every {@link PotionRecipe} using real-time or rolling-average prices,
 * applies OSRS Grand Exchange tax rules, and flags missing, stale, or volatile market data.
 */
@Singleton
public class PotionProfitCalculator
{
	public static final long DEFAULT_STALE_THRESHOLD_SECONDS = 3 * 3600L; // 3 hours
	public static final double DEFAULT_VOLATILITY_SPREAD_PERCENT = 15.0; // 15% high/low spread

	private final GeTaxCalculator geTaxCalculator;
	private final ProductionTimeCalculator productionTimeCalculator;

	@Inject
	public PotionProfitCalculator(
		GeTaxCalculator geTaxCalculator,
		ProductionTimeCalculator productionTimeCalculator)
	{
		this.geTaxCalculator = geTaxCalculator != null ? geTaxCalculator : new GeTaxCalculator();
		this.productionTimeCalculator = productionTimeCalculator != null
			? productionTimeCalculator
			: new ProductionTimeCalculator();
	}

	public PotionProfitCalculator()
	{
		this(new GeTaxCalculator(), new ProductionTimeCalculator());
	}

	/**
	 * Evaluates a single {@link PotionRecipe} with default staleness/volatility thresholds.
	 */
	public PotionProfitResult calculate(
		PotionRecipe recipe,
		Map<Integer, ItemPrice> priceMap,
		PriceCalculationMode priceMode,
		boolean includeGeTax,
		int playerHerbloreLevel,
		long playerBudgetGp,
		long nowEpochSec)
	{
		return calculate(
			recipe,
			priceMap,
			priceMode,
			includeGeTax,
			playerHerbloreLevel,
			playerBudgetGp,
			nowEpochSec,
			true,
			DEFAULT_STALE_THRESHOLD_SECONDS,
			true,
			DEFAULT_VOLATILITY_SPREAD_PERCENT
		);
	}

	/**
	 * Evaluates a single {@link PotionRecipe} with full configuration controls.
	 */
	public PotionProfitResult calculate(
		PotionRecipe recipe,
		Map<Integer, ItemPrice> priceMap,
		PriceCalculationMode priceMode,
		boolean includeGeTax,
		int playerHerbloreLevel,
		long playerBudgetGp,
		long nowEpochSec,
		boolean enableStaleWarnings,
		long maxStaleAgeSeconds,
		boolean enableVolatilityWarnings,
		double maxVolatilitySpreadPct)
	{
		PriceCalculationMode safeMode = priceMode != null ? priceMode : PriceCalculationMode.INSTANT_CONSERVATIVE;
		int safePlayerLevel = Math.max(1, playerHerbloreLevel);

		if (recipe == null || !recipe.isVerified() || recipe.getPotionItemId() <= 0 || recipe.getIngredients().isEmpty())
		{
			return PotionProfitResult.builder()
				.recipe(recipe)
				.priceMode(safeMode)
				.includeGeTax(includeGeTax)
				.priceStatus(PriceStatus.MISSING_DATA)
				.hasCompletePriceData(false)
				.hasIngredientPriceData(false)
				.statusMessage("Unverified or incomplete recipe definition")
				.availableAtPlayerLevel(false)
				.affordableWithinBudget(false)
				.build();
		}

		boolean availableAtLevel = safePlayerLevel >= recipe.getRequiredLevel();
		int levelsUntilUnlock = Math.max(0, recipe.getRequiredLevel() - safePlayerLevel);
		int potionsPerHour = productionTimeCalculator.getEstimatedPotionsPerHour(recipe);
		long xpPerHour = productionTimeCalculator.calculateEstimatedXpPerHour(recipe);

		if (priceMap == null || priceMap.isEmpty())
		{
			return PotionProfitResult.builder()
				.recipe(recipe)
				.priceMode(safeMode)
				.includeGeTax(includeGeTax)
				.priceStatus(PriceStatus.MISSING_DATA)
				.hasCompletePriceData(false)
				.hasIngredientPriceData(false)
				.statusMessage("Market price data unavailable")
				.xpPerPotion(recipe.getXpGained())
				.estimatedPotionsPerHour(potionsPerHour)
				.estimatedXpPerHour(xpPerHour)
				.availableAtPlayerLevel(availableAtLevel)
				.levelsUntilUnlock(levelsUntilUnlock)
				.affordableWithinBudget(false)
				.build();
		}

		Map<Integer, Long> unitPrices = new LinkedHashMap<>();
		Map<Integer, Long> lineCosts = new LinkedHashMap<>();
		long totalIngredientCost = 0L;
		boolean allIngredientsPriced = true;
		boolean anyStale = false;
		boolean anyVolatile = false;
		long maxAgeSec = 0L;
		String missingNote = null;

		for (PotionIngredient ing : recipe.getIngredients())
		{
			if (ing == null || ing.getItemId() <= 0 || ing.getQuantity() <= 0)
			{
				allIngredientsPriced = false;
				missingNote = "Invalid ingredient specification";
				break;
			}
			if (!ing.isTradeable())
			{
				unitPrices.put(ing.getItemId(), 0L);
				lineCosts.put(ing.getItemId(), 0L);
				missingNote = "Includes untradeable catalyst: " + ing.getName() + " (valued at 0 GP direct GE cost)";
				continue;
			}

			ItemPrice ingPrice = priceMap.get(ing.getItemId());
			Long resolvedBuy = ingPrice != null ? ingPrice.resolveBuyPrice(safeMode) : null;
			if (resolvedBuy == null || resolvedBuy <= 0L)
			{
				allIngredientsPriced = false;
				missingNote = "Missing market price for " + ing.getName();
				continue;
			}

			try
			{
				long lineCost = Math.multiplyExact(resolvedBuy, (long) ing.getQuantity());
				totalIngredientCost = Math.addExact(totalIngredientCost, lineCost);
				unitPrices.put(ing.getItemId(), resolvedBuy);
				lineCosts.merge(ing.getItemId(), lineCost, Math::addExact);
			}
			catch (ArithmeticException ex)
			{
				allIngredientsPriced = false;
				missingNote = "Price calculation overflow for " + ing.getName();
				break;
			}

			long age = ingPrice.getAgeSeconds(nowEpochSec);
			maxAgeSec = Math.max(maxAgeSec, age);
			if (ingPrice.isStale(nowEpochSec, maxStaleAgeSeconds) || ingPrice.isFromCache())
			{
				anyStale = true;
			}
			if (ingPrice.isVolatile(maxVolatilitySpreadPct))
			{
				anyVolatile = true;
			}
		}

		double xp = Math.max(0.0, recipe.getXpGained());
		double ingredientCostPerXp = (allIngredientsPriced && xp > 0.0)
			? ((double) totalIngredientCost / xp)
			: 0.0;
		boolean affordable = allIngredientsPriced && playerBudgetGp >= totalIngredientCost && totalIngredientCost > 0L;

		// Check finished potion price
		if (!recipe.isTradeableOutput())
		{
			return PotionProfitResult.builder()
				.recipe(recipe)
				.priceMode(safeMode)
				.includeGeTax(includeGeTax)
				.priceStatus(PriceStatus.MISSING_DATA)
				.hasCompletePriceData(false)
				.hasIngredientPriceData(allIngredientsPriced)
				.stalePriceWarning(enableStaleWarnings && anyStale)
				.volatilePriceWarning(enableVolatilityWarnings && anyVolatile)
				.statusMessage(allIngredientsPriced
					? "Untradeable finished potion (cannot be sold on GE)"
					: (missingNote != null ? missingNote : "Untradeable recipe"))
				.ingredientUnitPrices(unitPrices)
				.ingredientLineCosts(lineCosts)
				.totalIngredientCost(allIngredientsPriced ? totalIngredientCost : 0L)
				.xpPerPotion(xp)
				.ingredientCostPerXp(ingredientCostPerXp)
				.netCostPerXp(ingredientCostPerXp)
				.netLossPerXp(ingredientCostPerXp)
				.profitPerXp(-ingredientCostPerXp)
				.estimatedPotionsPerHour(potionsPerHour)
				.estimatedXpPerHour(xpPerHour)
				.maxPriceAgeSeconds(maxAgeSec)
				.availableAtPlayerLevel(availableAtLevel)
				.levelsUntilUnlock(levelsUntilUnlock)
				.affordableWithinBudget(affordable)
				.build();
		}

		ItemPrice finishedPriceObj = priceMap.get(recipe.getPotionItemId());
		Long unitSellPrice = finishedPriceObj != null ? finishedPriceObj.resolveSellPrice(safeMode) : null;

		if (!allIngredientsPriced || unitSellPrice == null || unitSellPrice <= 0L)
		{
			String msg = missingNote != null
				? missingNote
				: ("Missing market price for " + recipe.getPotionName());
			return PotionProfitResult.builder()
				.recipe(recipe)
				.priceMode(safeMode)
				.includeGeTax(includeGeTax)
				.priceStatus(PriceStatus.MISSING_DATA)
				.hasCompletePriceData(false)
				.hasIngredientPriceData(allIngredientsPriced)
				.stalePriceWarning(enableStaleWarnings && anyStale)
				.volatilePriceWarning(enableVolatilityWarnings && anyVolatile)
				.statusMessage(msg)
				.ingredientUnitPrices(unitPrices)
				.ingredientLineCosts(lineCosts)
				.totalIngredientCost(allIngredientsPriced ? totalIngredientCost : 0L)
				.xpPerPotion(xp)
				.ingredientCostPerXp(ingredientCostPerXp)
				.estimatedPotionsPerHour(potionsPerHour)
				.estimatedXpPerHour(xpPerHour)
				.maxPriceAgeSeconds(maxAgeSec)
				.availableAtPlayerLevel(availableAtLevel)
				.levelsUntilUnlock(levelsUntilUnlock)
				.affordableWithinBudget(affordable)
				.build();
		}

		long ageOut = finishedPriceObj.getAgeSeconds(nowEpochSec);
		maxAgeSec = Math.max(maxAgeSec, ageOut);
		if (finishedPriceObj.isStale(nowEpochSec, maxStaleAgeSeconds) || finishedPriceObj.isFromCache())
		{
			anyStale = true;
		}
		if (finishedPriceObj.isVolatile(maxVolatilitySpreadPct))
		{
			anyVolatile = true;
		}

		int outputQty = Math.max(1, recipe.getOutputQuantity());
		long grossSaleValue;
		long geTax;
		long netSaleValue;
		long netProfit;
		long profit100;
		long profit1000;
		long profit10000;
		long profitPerHour;

		try
		{
			grossSaleValue = Math.multiplyExact(unitSellPrice, (long) outputQty);
			geTax = geTaxCalculator.calculateTotalTax(recipe.getPotionItemId(), unitSellPrice, outputQty, includeGeTax);
			netSaleValue = Math.subtractExact(grossSaleValue, geTax);
			netProfit = Math.subtractExact(netSaleValue, totalIngredientCost);
			profit100 = Math.multiplyExact(netProfit, 100L);
			profit1000 = Math.multiplyExact(netProfit, 1_000L);
			profit10000 = Math.multiplyExact(netProfit, 10_000L);
			profitPerHour = productionTimeCalculator.calculateEstimatedProfitPerHour(recipe, netProfit);
		}
		catch (ArithmeticException ex)
		{
			return PotionProfitResult.builder()
				.recipe(recipe)
				.priceMode(safeMode)
				.includeGeTax(includeGeTax)
				.priceStatus(PriceStatus.MISSING_DATA)
				.hasCompletePriceData(false)
				.statusMessage("Arithmetic overflow during profit calculation")
				.build();
		}

		double profitMarginPct = totalIngredientCost > 0L
			? (((double) netProfit / (double) totalIngredientCost) * 100.0)
			: 0.0;

		double netCostPerXp = 0.0;
		double netLossPerXp = 0.0;
		double profitPerXp = 0.0;
		if (xp > 0.0)
		{
			// Positive netCostPerXp means it costs GP per XP; negative means you profit per XP
			netCostPerXp = (double) (totalIngredientCost - netSaleValue) / xp;
			netLossPerXp = netProfit < 0L ? ((double) (-netProfit) / xp) : 0.0;
			profitPerXp = (double) netProfit / xp;
		}

		int hourlyVol = finishedPriceObj.getTotalVolume1h();
		boolean warnStale = enableStaleWarnings && anyStale;
		boolean warnVolatile = enableVolatilityWarnings && anyVolatile;

		PriceStatus status;
		String statusMsg;
		if (warnStale || warnVolatile)
		{
			status = PriceStatus.UNCERTAIN_OR_STALE;
			if (warnStale && warnVolatile)
			{
				statusMsg = "Stale & volatile market prices";
			}
			else if (warnStale)
			{
				statusMsg = finishedPriceObj.isFromCache() ? "Cached price snapshot" : "Stale price data";
			}
			else
			{
				statusMsg = "High price spread / volatility";
			}
		}
		else if (netProfit >= 0L)
		{
			status = PriceStatus.PROFITABLE;
			statusMsg = "Profitable";
		}
		else
		{
			status = PriceStatus.LOSS;
			statusMsg = "Training loss";
		}

		double trainingScore = computeBalancedTrainingScore(
			recipe,
			netProfit,
			netCostPerXp,
			xpPerHour,
			hourlyVol,
			warnStale,
			warnVolatile
		);

		return PotionProfitResult.builder()
			.recipe(recipe)
			.priceMode(safeMode)
			.includeGeTax(includeGeTax)
			.priceStatus(status)
			.hasCompletePriceData(true)
			.hasIngredientPriceData(true)
			.stalePriceWarning(warnStale)
			.volatilePriceWarning(warnVolatile)
			.statusMessage(statusMsg)
			.ingredientUnitPrices(unitPrices)
			.ingredientLineCosts(lineCosts)
			.totalIngredientCost(totalIngredientCost)
			.finishedPotionSalePrice(grossSaleValue)
			.geTax(geTax)
			.netSaleValue(netSaleValue)
			.netProfitPerPotion(netProfit)
			.profitFor100(profit100)
			.profitFor1000(profit1000)
			.profitFor10000(profit10000)
			.profitMarginPercent(profitMarginPct)
			.xpPerPotion(xp)
			.ingredientCostPerXp(ingredientCostPerXp)
			.netCostPerXp(netCostPerXp)
			.netLossPerXp(netLossPerXp)
			.profitPerXp(profitPerXp)
			.estimatedPotionsPerHour(potionsPerHour)
			.estimatedXpPerHour(xpPerHour)
			.estimatedProfitPerHour(profitPerHour)
			.hourlyVolume(hourlyVol)
			.maxPriceAgeSeconds(maxAgeSec)
			.overallTrainingScore(trainingScore)
			.availableAtPlayerLevel(availableAtLevel)
			.levelsUntilUnlock(levelsUntilUnlock)
			.affordableWithinBudget(affordable)
			.build();
	}

	/**
	 * Evaluates a batch of recipes and returns all results in deterministic order.
	 */
	public List<PotionProfitResult> calculateAll(
		List<PotionRecipe> recipes,
		Map<Integer, ItemPrice> priceMap,
		PriceCalculationMode priceMode,
		boolean includeGeTax,
		int playerHerbloreLevel,
		long playerBudgetGp,
		long nowEpochSec,
		boolean enableStaleWarnings,
		long maxStaleAgeSeconds,
		boolean enableVolatilityWarnings,
		double maxVolatilitySpreadPct)
	{
		if (recipes == null || recipes.isEmpty())
		{
			return Collections.emptyList();
		}
		List<PotionProfitResult> results = new ArrayList<>(recipes.size());
		for (PotionRecipe recipe : recipes)
		{
			results.add(calculate(
				recipe,
				priceMap,
				priceMode,
				includeGeTax,
				playerHerbloreLevel,
				playerBudgetGp,
				nowEpochSec,
				enableStaleWarnings,
				maxStaleAgeSeconds,
				enableVolatilityWarnings,
				maxVolatilitySpreadPct
			));
		}
		return results;
	}

	private double computeBalancedTrainingScore(
		PotionRecipe recipe,
		long netProfit,
		double netCostPerXp,
		long xpPerHour,
		int hourlyVolume,
		boolean stale,
		boolean volatilePrice)
	{
		if (recipe.isUnfinishedPotionRecipe() || recipe.getXpGained() <= 0.0)
		{
			return 0.0;
		}

		// 1. XP Rate Score (0..35 points, normalized against 450,000 XP/hr ceiling)
		double xpRateNorm = Math.min(1.0, (double) xpPerHour / 450_000.0);
		double xpComponent = xpRateNorm * 35.0;

		// 2. Cost/Profit Efficiency Score (0..35 points)
		// Profitable or break-even gets 28..35 pts; 10 GP/XP loss gets ~17.5 pts; >=25 GP/XP loss gets 0 pts
		double efficiencyComponent;
		if (netCostPerXp <= 0.0)
		{
			double bonus = Math.min(7.0, (-netCostPerXp) * 1.5);
			efficiencyComponent = 28.0 + bonus;
		}
		else
		{
			efficiencyComponent = Math.max(0.0, 28.0 * (1.0 - (netCostPerXp / 25.0)));
		}

		// 3. Market Liquidity Score (0..20 points, logarithmic on hourly volume)
		double volumeComponent = 0.0;
		if (hourlyVolume > 0)
		{
			double logVol = Math.log10(hourlyVolume + 1.0); // log10(100,000) = 5.0
			volumeComponent = Math.min(20.0, (logVol / 5.0) * 20.0);
		}

		// 4. Reliability & Freshness Score (0..10 points)
		double reliabilityComponent = 10.0;
		if (stale)
		{
			reliabilityComponent -= 5.0;
		}
		if (volatilePrice)
		{
			reliabilityComponent -= 4.0;
		}
		if (netProfit > -500L && netProfit < 500L)
		{
			reliabilityComponent += 1.0;
		}
		reliabilityComponent = Math.max(0.0, Math.min(10.0, reliabilityComponent));

		double total = xpComponent + efficiencyComponent + volumeComponent + reliabilityComponent;
		return Math.round(total * 10.0) / 10.0;
	}
}

package com.herbwise.calculators;

import com.herbwise.models.PotionIngredient;
import com.herbwise.models.PotionRecipe;
import javax.inject.Singleton;
import net.runelite.api.ItemID;

/**
 * Calculates realistic OSRS Herblore production rates, potions per inventory load,
 * and estimated training duration based on ingredient stackability and recipe steps.
 */
@Singleton
public class ProductionTimeCalculator
{
	public static final int INVENTORY_SLOTS = 28;
	public static final int DEFAULT_STANDARD_POTIONS_PER_HOUR = 2500;
	public static final int DEFAULT_STACKABLE_POTIONS_PER_HOUR = 2700;
	public static final int DEFAULT_TWO_STEP_POTIONS_PER_HOUR = 1200;

	/**
	 * Determines how many potions can be mixed in a single 28-slot OSRS inventory load.
	 * - 1 non-stackable potion + 1 stackable secondary (e.g. Amylase, Zulrah's scales, Lava scale shards): 27 per inventory.
	 * - 1 non-stackable unf potion + 1 non-stackable secondary: 14 per inventory.
	 * - 3 non-stackable items (e.g. Herb + Vial + Secondary): 9 per inventory.
	 * - 4 non-stackable items (e.g. Super combat potion: Torstol + 3 potions): 7 per inventory.
	 */
	public int getPotionsPerInventoryLoad(PotionRecipe recipe)
	{
		if (recipe == null || recipe.getIngredients().isEmpty())
		{
			return 14;
		}

		int nonStackableSlotsPerPotion = 0;
		int stackableTypesCount = 0;

		for (PotionIngredient ing : recipe.getIngredients())
		{
			if (isStackableIngredient(ing.getItemId()))
			{
				stackableTypesCount++;
			}
			else
			{
				nonStackableSlotsPerPotion += Math.max(1, ing.getQuantity());
			}
		}

		if (nonStackableSlotsPerPotion <= 0)
		{
			return 27;
		}

		int availableSlotsForNonStackables = INVENTORY_SLOTS - stackableTypesCount;
		int perLoad = availableSlotsForNonStackables / nonStackableSlotsPerPotion;
		return Math.max(1, perLoad);
	}

	/**
	 * Calculates total bank inventory loads needed to produce {@code totalPotions}.
	 */
	public long calculateInventoryLoads(PotionRecipe recipe, long totalPotions)
	{
		if (totalPotions <= 0L)
		{
			return 0L;
		}
		int perLoad = getPotionsPerInventoryLoad(recipe);
		return (totalPotions + perLoad - 1L) / perLoad;
	}

	/**
	 * Returns the estimated potions mixed per hour for a given recipe.
	 */
	public int getEstimatedPotionsPerHour(PotionRecipe recipe)
	{
		if (recipe == null)
		{
			return DEFAULT_STANDARD_POTIONS_PER_HOUR;
		}
		if (recipe.getPotionsPerHourEstimate() > 0)
		{
			return recipe.getPotionsPerHourEstimate();
		}
		int perLoad = getPotionsPerInventoryLoad(recipe);
		if (perLoad >= 27)
		{
			return DEFAULT_STACKABLE_POTIONS_PER_HOUR;
		}
		if (perLoad <= 9)
		{
			return DEFAULT_TWO_STEP_POTIONS_PER_HOUR;
		}
		return DEFAULT_STANDARD_POTIONS_PER_HOUR;
	}

	/**
	 * Calculates estimated Herblore XP gained per hour.
	 */
	public long calculateEstimatedXpPerHour(PotionRecipe recipe)
	{
		if (recipe == null || recipe.getXpGained() <= 0.0)
		{
			return 0L;
		}
		int perHour = getEstimatedPotionsPerHour(recipe);
		return Math.round(recipe.getXpGained() * perHour);
	}

	/**
	 * Calculates estimated GP profit/loss per hour.
	 */
	public long calculateEstimatedProfitPerHour(PotionRecipe recipe, long netProfitPerPotion)
	{
		if (recipe == null)
		{
			return 0L;
		}
		int perHour = getEstimatedPotionsPerHour(recipe);
		return Math.multiplyExact(netProfitPerPotion, (long) perHour);
	}

	/**
	 * Calculates estimated hours needed to produce {@code totalPotions}.
	 */
	public double calculateHoursRequired(PotionRecipe recipe, long totalPotions)
	{
		if (totalPotions <= 0L)
		{
			return 0.0;
		}
		int perHour = getEstimatedPotionsPerHour(recipe);
		return (double) totalPotions / (double) Math.max(1, perHour);
	}

	/**
	 * Calculates estimated minutes needed to produce {@code totalPotions}.
	 */
	public double calculateMinutesRequired(PotionRecipe recipe, long totalPotions)
	{
		return calculateHoursRequired(recipe, totalPotions) * 60.0;
	}

	/**
	 * Formats a duration in minutes into a concise human-readable string (e.g. "2h 15m" or "18 min").
	 */
	public static String formatDurationMinutes(double totalMinutes)
	{
		if (totalMinutes <= 0.0)
		{
			return "0 min";
		}
		long roundedMin = Math.max(1L, Math.round(totalMinutes));
		if (roundedMin < 60L)
		{
			return roundedMin + " min";
		}
		long hours = roundedMin / 60L;
		long mins = roundedMin % 60L;
		return mins > 0 ? (hours + "h " + mins + "m") : (hours + "h");
	}

	public static boolean isStackableIngredient(int itemId)
	{
		switch (itemId)
		{
			case ItemID.AMYLASE_CRYSTAL:
			case ItemID.LAVA_SCALE_SHARD:
			case ItemID.ZULRAHS_SCALES:
			case ItemID.NIHIL_DUST:
			case ItemID.ANCIENT_ESSENCE:
			case ItemID.VOLCANIC_ASH:
			case ItemID.CRUSHED_SUPERIOR_DRAGON_BONES:
			case ItemID.ARAXYTE_VENOM_SAC:
			case ItemID.CRYSTAL_DUST:
			case ItemID.NAIL_BEAST_NAILS:
			case ItemID.MOONLIGHT_GRUB_PASTE:
				return true;
			default:
				return false;
		}
	}
}

package com.herbwise.calculators;

import com.herbwise.models.PotionProfitResult;
import com.herbwise.models.PotionRecipe;
import com.herbwise.models.TrainingRecommendation;
import com.herbwise.models.TrainingRecommendation.Category;
import java.text.NumberFormat;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.stream.Collectors;
import javax.inject.Singleton;

/**
 * Intelligent Herblore training and profit recommendation engine.
 * Evaluates verified recipes across six distinct categories using transparent scoring
 * and generates dynamic, data-backed explanations for every recommendation.
 */
@Singleton
public class TrainingRecommendationEngine
{
	private static final NumberFormat GP_FORMAT = NumberFormat.getIntegerInstance(Locale.US);

	/**
	 * Generates all 6 recommendation categories based on the current market results,
	 * player Herblore level, and GP budget.
	 */
	public Map<Category, TrainingRecommendation> generateRecommendations(
		List<PotionProfitResult> allResults,
		int playerHerbloreLevel,
		long playerBudgetGp,
		boolean restrictAllToPlayerLevel)
	{
		Map<Category, TrainingRecommendation> map = new LinkedHashMap<>();
		if (allResults == null || allResults.isEmpty())
		{
			return map;
		}

		int effectiveLevel = Math.max(1, playerHerbloreLevel);
		long effectiveBudget = Math.max(0L, playerBudgetGp);

		// Base candidate pool: verified, completed potions with complete market data and tradeable GE ingredients
		List<PotionProfitResult> validCompleted = allResults.stream()
			.filter(r -> r != null && r.getRecipe() != null && r.getRecipe().isVerified())
			.filter(r -> !r.getRecipe().isUnfinishedPotionRecipe())
			.filter(r -> !r.getRecipe().isAlternativeRecipe())
			.filter(r -> r.getRecipe().getIngredients().stream().allMatch(com.herbwise.models.PotionIngredient::isTradeable))
			.filter(PotionProfitResult::isHasCompletePriceData)
			.collect(Collectors.toList());

		if (validCompleted.isEmpty())
		{
			return map;
		}

		List<PotionProfitResult> levelFilteredPool = validCompleted.stream()
			.filter(r -> r.getRecipe().getRequiredLevel() <= effectiveLevel)
			.collect(Collectors.toList());

		List<PotionProfitResult> generalPool = restrictAllToPlayerLevel && !levelFilteredPool.isEmpty()
			? levelFilteredPool
			: validCompleted;

		// A. BEST PROFIT
		findBestProfit(generalPool, effectiveLevel).ifPresent(rec -> map.put(Category.BEST_PROFIT, rec));

		// B. CHEAPEST XP (requires meaningful training XP > 15 XP per potion)
		findCheapestXp(generalPool, effectiveLevel).ifPresent(rec -> map.put(Category.CHEAPEST_XP, rec));

		// C. BEST XP RATE
		findBestXpRate(generalPool, effectiveLevel).ifPresent(rec -> map.put(Category.BEST_XP_RATE, rec));

		// D. BEST BALANCED OPTION
		findBestBalanced(generalPool, effectiveLevel).ifPresent(rec -> map.put(Category.BEST_BALANCED, rec));

		// E. BEST FOR MY BUDGET
		List<PotionProfitResult> budgetPool = !levelFilteredPool.isEmpty() ? levelFilteredPool : generalPool;
		findBestForBudget(budgetPool, effectiveLevel, effectiveBudget)
			.ifPresent(rec -> map.put(Category.BEST_FOR_BUDGET, rec));

		// F. BEST FOR MY LEVEL
		List<PotionProfitResult> myLevelPool = !levelFilteredPool.isEmpty() ? levelFilteredPool : validCompleted;
		findBestForLevel(myLevelPool, effectiveLevel)
			.ifPresent(rec -> map.put(Category.BEST_FOR_LEVEL, rec));

		return map;
	}

	private Optional<TrainingRecommendation> findBestProfit(List<PotionProfitResult> pool, int playerLevel)
	{
		return pool.stream()
			.max(Comparator.comparingLong(PotionProfitResult::getNetProfitPerPotion)
				.thenComparingInt(PotionProfitResult::getHourlyVolume))
			.map(best -> {
				PotionRecipe rec = best.getRecipe();
				List<String> reasons = new ArrayList<>();
				String profitStr = formatSignedGp(best.getNetProfitPerPotion());
				reasons.add("Highest net profit at " + profitStr + " per potion ("
					+ formatSignedGp(best.getProfitFor1000()) + " per 1,000 made).");
				reasons.add(String.format(Locale.US,
					"Ingredient cost %s GP vs %s GP net sale after %s GP GE tax (%.1f%% margin).",
					GP_FORMAT.format(best.getTotalIngredientCost()),
					GP_FORMAT.format(best.getNetSaleValue()),
					GP_FORMAT.format(best.getGeTax()),
					best.getProfitMarginPercent()
				));
				reasons.add(buildLevelReason(rec, playerLevel));
				reasons.add(buildLiquidityReason(best));

				String headline = profitStr + "/potion (" + formatSignedGp(best.getEstimatedProfitPerHour()) + "/hr)";
				double score = Math.min(100.0, Math.max(0.0, 50.0 + (best.getNetProfitPerPotion() / 40.0)));
				return new TrainingRecommendation(Category.BEST_PROFIT, best, score, headline, reasons);
			});
	}

	private Optional<TrainingRecommendation> findCheapestXp(List<PotionProfitResult> pool, int playerLevel)
	{
		List<PotionProfitResult> trainingCandidates = pool.stream()
			.filter(r -> r.getXpPerPotion() >= 20.0)
			.collect(Collectors.toList());
		if (trainingCandidates.isEmpty())
		{
			trainingCandidates = pool;
		}

		return trainingCandidates.stream()
			.min(Comparator.comparingDouble(PotionProfitResult::getNetCostPerXp)
				.thenComparing(Comparator.comparingDouble(PotionProfitResult::getXpPerPotion).reversed()))
			.map(best -> {
				PotionRecipe rec = best.getRecipe();
				List<String> reasons = new ArrayList<>();
				if (best.getNetCostPerXp() <= 0.0)
				{
					reasons.add(String.format(Locale.US,
						"Profitable training! Earns +%.2f GP per XP (%s GP profit per potion) while granting %.1f XP.",
						Math.abs(best.getNetCostPerXp()),
						GP_FORMAT.format(best.getNetProfitPerPotion()),
						best.getXpPerPotion()
					));
				}
				else
				{
					reasons.add(String.format(Locale.US,
						"Lowest net training cost at %.2f GP per XP (%s GP loss for %.1f XP).",
						best.getNetCostPerXp(),
						GP_FORMAT.format(Math.abs(best.getNetProfitPerPotion())),
						best.getXpPerPotion()
					));
				}
				reasons.add("Raw ingredient outlay is only " + GP_FORMAT.format(best.getTotalIngredientCost())
					+ " GP per potion (" + String.format(Locale.US, "%.2f GP/XP gross", best.getIngredientCostPerXp()) + ").");
				reasons.add(buildLevelReason(rec, playerLevel));
				reasons.add(buildLiquidityReason(best));

				String headline = best.getNetCostPerXp() <= 0.0
					? String.format(Locale.US, "+%.2f GP/XP (Profitable)", Math.abs(best.getNetCostPerXp()))
					: String.format(Locale.US, "%.2f GP/XP", best.getNetCostPerXp());
				return new TrainingRecommendation(Category.CHEAPEST_XP, best, best.getOverallTrainingScore(), headline, reasons);
			});
	}

	private Optional<TrainingRecommendation> findBestXpRate(List<PotionProfitResult> pool, int playerLevel)
	{
		return pool.stream()
			.max(Comparator.comparingLong(PotionProfitResult::getEstimatedXpPerHour)
				.thenComparingDouble(PotionProfitResult::getXpPerPotion))
			.map(best -> {
				PotionRecipe rec = best.getRecipe();
				List<String> reasons = new ArrayList<>();
				reasons.add("Delivers an estimated " + GP_FORMAT.format(best.getEstimatedXpPerHour())
					+ " XP/hr at ~" + GP_FORMAT.format(best.getEstimatedPotionsPerHour()) + " potions/hr.");
				reasons.add(String.format(Locale.US,
					"Grants %.1f Herblore XP per potion with %s GP/potion net %s.",
					best.getXpPerPotion(),
					GP_FORMAT.format(Math.abs(best.getNetProfitPerPotion())),
					best.getNetProfitPerPotion() >= 0 ? "profit" : "cost"
				));
				reasons.add(buildLevelReason(rec, playerLevel));
				reasons.add(buildLiquidityReason(best));

				String headline = GP_FORMAT.format(best.getEstimatedXpPerHour()) + " XP/hr ("
					+ String.format(Locale.US, "%.1f XP each", best.getXpPerPotion()) + ")";
				return new TrainingRecommendation(Category.BEST_XP_RATE, best, best.getOverallTrainingScore(), headline, reasons);
			});
	}

	private Optional<TrainingRecommendation> findBestBalanced(List<PotionProfitResult> pool, int playerLevel)
	{
		List<PotionProfitResult> trainingPool = pool.stream()
			.filter(r -> r.getXpPerPotion() >= 25.0)
			.collect(Collectors.toList());
		if (trainingPool.isEmpty())
		{
			trainingPool = pool;
		}

		return trainingPool.stream()
			.max(Comparator.comparingDouble(PotionProfitResult::getOverallTrainingScore))
			.map(best -> {
				PotionRecipe rec = best.getRecipe();
				List<String> reasons = new ArrayList<>();
				reasons.add(String.format(Locale.US,
					"Highest composite training score (%.1f / 100) balancing XP speed, GP/XP efficiency, and liquidity.",
					best.getOverallTrainingScore()
				));
				reasons.add(String.format(Locale.US,
					"Combines %s XP/hr with %s (%s GP per potion).",
					GP_FORMAT.format(best.getEstimatedXpPerHour()),
					best.getNetCostPerXp() <= 0.0
						? String.format(Locale.US, "+%.2f GP/XP profit", Math.abs(best.getNetCostPerXp()))
						: String.format(Locale.US, "%.2f GP/XP net cost", best.getNetCostPerXp()),
					formatSignedGp(best.getNetProfitPerPotion())
				));
				reasons.add(buildLevelReason(rec, playerLevel));
				reasons.add(buildLiquidityReason(best));

				String headline = String.format(Locale.US, "Score %.1f/100 • %s XP/hr",
					best.getOverallTrainingScore(),
					GP_FORMAT.format(best.getEstimatedXpPerHour()));
				return new TrainingRecommendation(Category.BEST_BALANCED, best, best.getOverallTrainingScore(), headline, reasons);
			});
	}

	private Optional<TrainingRecommendation> findBestForBudget(
		List<PotionProfitResult> pool,
		int playerLevel,
		long budgetGp)
	{
		List<PotionProfitResult> affordable = pool.stream()
			.filter(r -> r.getXpPerPotion() >= 20.0)
			.filter(r -> r.getTotalIngredientCost() > 0L && r.getTotalIngredientCost() <= budgetGp)
			.collect(Collectors.toList());

		if (affordable.isEmpty())
		{
			// Fallback to lowest-cost recipe in pool if budget is very small
			affordable = pool.stream()
				.filter(r -> r.getTotalIngredientCost() > 0L)
				.sorted(Comparator.comparingLong(PotionProfitResult::getTotalIngredientCost))
				.limit(3)
				.collect(Collectors.toList());
		}

		return affordable.stream()
			.max(Comparator.comparingDouble(r -> {
				long count = budgetGp > 0 ? (budgetGp / Math.max(1L, r.getTotalIngredientCost())) : 0L;
				return r.getOverallTrainingScore() + Math.min(20.0, Math.log10(count + 1.0) * 6.5);
			}))
			.map(best -> {
				long maxAffordable = budgetGp > 0L
					? (budgetGp / Math.max(1L, best.getTotalIngredientCost()))
					: 0L;
				double totalXp = maxAffordable * best.getXpPerPotion();
				List<String> reasons = new ArrayList<>();
				reasons.add("Your " + GP_FORMAT.format(budgetGp) + " GP budget affords "
					+ GP_FORMAT.format(maxAffordable) + " potions ("
					+ GP_FORMAT.format(Math.round(totalXp)) + " total Herblore XP).");
				reasons.add("Costs " + GP_FORMAT.format(best.getTotalIngredientCost())
					+ " GP per potion in ingredients and returns "
					+ GP_FORMAT.format(best.getNetSaleValue()) + " GP after GE tax.");
				reasons.add(buildLevelReason(best.getRecipe(), playerLevel));
				reasons.add(buildLiquidityReason(best));

				String headline = GP_FORMAT.format(maxAffordable) + " potions ("
					+ GP_FORMAT.format(Math.round(totalXp)) + " XP)";
				return new TrainingRecommendation(Category.BEST_FOR_BUDGET, best, best.getOverallTrainingScore(), headline, reasons);
			});
	}

	private Optional<TrainingRecommendation> findBestForLevel(List<PotionProfitResult> pool, int playerLevel)
	{
		List<PotionProfitResult> unlocked = pool.stream()
			.filter(r -> r.getRecipe().getRequiredLevel() <= playerLevel)
			.filter(r -> r.getXpPerPotion() >= 25.0)
			.collect(Collectors.toList());

		if (unlocked.isEmpty())
		{
			unlocked = pool;
		}

		return unlocked.stream()
			.max(Comparator.comparingDouble((PotionProfitResult r) -> {
				// Favour recipes close to the player's current tier that also have strong balanced score
				int levelGap = Math.max(0, playerLevel - r.getRecipe().getRequiredLevel());
				double tierProximityBonus = Math.max(0.0, 18.0 - (levelGap * 0.45));
				return r.getOverallTrainingScore() + tierProximityBonus;
			}))
			.map(best -> {
				PotionRecipe rec = best.getRecipe();
				List<String> reasons = new ArrayList<>();
				reasons.add("Available now at your current Herblore level (" + playerLevel
					+ " vs Level " + rec.getRequiredLevel() + " requirement).");
				reasons.add(String.format(Locale.US,
					"Provides %.1f XP per potion (%s XP/hr) at %s.",
					best.getXpPerPotion(),
					GP_FORMAT.format(best.getEstimatedXpPerHour()),
					best.getNetCostPerXp() <= 0.0
						? (formatSignedGp(best.getNetProfitPerPotion()) + " profit/potion")
						: String.format(Locale.US, "%.2f GP/XP", best.getNetCostPerXp())
				));
				reasons.add("Uses " + rec.getFormattedIngredientList() + ".");
				reasons.add(buildLiquidityReason(best));

				String headline = "Lvl " + rec.getRequiredLevel() + " • "
					+ String.format(Locale.US, "%.1f XP", best.getXpPerPotion()) + " ("
					+ formatSignedGp(best.getNetProfitPerPotion()) + ")";
				return new TrainingRecommendation(Category.BEST_FOR_LEVEL, best, best.getOverallTrainingScore(), headline, reasons);
			});
	}

	private static String buildLevelReason(PotionRecipe recipe, int playerLevel)
	{
		if (playerLevel >= recipe.getRequiredLevel())
		{
			return "Unlocked at your current Herblore level (Requires Lvl " + recipe.getRequiredLevel()
				+ ", you are Lvl " + playerLevel + ").";
		}
		int diff = recipe.getRequiredLevel() - playerLevel;
		return "Requires Level " + recipe.getRequiredLevel() + " Herblore (" + diff
			+ (diff == 1 ? " level" : " levels") + " above your current Lvl " + playerLevel + ").";
	}

	private static String buildLiquidityReason(PotionProfitResult result)
	{
		int vol = result.getHourlyVolume();
		String freshness = result.isStalePriceWarning()
			? "cached/older market snapshot"
			: "fresh live GE data";
		if (vol >= 50_000)
		{
			return "High Grand Exchange liquidity (~" + GP_FORMAT.format(vol) + " doses/potions traded per hour, " + freshness + ").";
		}
		if (vol >= 10_000)
		{
			return "Good market liquidity (~" + GP_FORMAT.format(vol) + " traded per hour, " + freshness + ").";
		}
		if (vol > 0)
		{
			return "Moderate trading volume (~" + GP_FORMAT.format(vol) + " traded per hour, " + freshness + ").";
		}
		return "Low recent trading volume; verify Grand Exchange offers before bulk buying.";
	}

	public static String formatSignedGp(long gp)
	{
		if (gp > 0L)
		{
			return "+" + GP_FORMAT.format(gp) + " GP";
		}
		return GP_FORMAT.format(gp) + " GP";
	}
}

package com.herbwise.data;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.ItemID;

/**
 * Defines Old School RuneScape Grand Exchange tax rules:
 * - Seller pays 2% tax (rounded down to the nearest whole GP per item).
 * - Items sold for under 50 GP incur 0 GP tax.
 * - Tax is capped at 5,000,000 GP per single item (sales >= 250,000,000 GP).
 * - Buying items on the Grand Exchange never incurs GE tax.
 * - Specific exempt items (such as Old School Bonds and untradeable items) are tax-exempt.
 */
public final class GeTaxRules
{
	/**
	 * Official OSRS GE tax rate (2% = 1 / 50).
	 */
	public static final double TAX_RATE = 0.02;

	/**
	 * Integer divisor equivalent to floor(price * 0.02) = price / 50.
	 */
	public static final long TAX_DIVISOR = 50L;

	/**
	 * Minimum sale price per item before any GE tax applies (items sold for < 50 GP pay 0 tax).
	 */
	public static final long MIN_TAXABLE_PRICE_GP = 50L;

	/**
	 * Maximum GE tax charged on a single item (5,000,000 GP cap).
	 */
	public static final long MAX_TAX_PER_ITEM_GP = 5_000_000L;

	/**
	 * Sale price threshold where the 5,000,000 GP cap is reached (250,000,000 GP).
	 */
	public static final long TAX_CAP_PRICE_THRESHOLD_GP = 250_000_000L;

	private static final Set<Integer> EXEMPT_ITEM_IDS;

	static
	{
		Set<Integer> exempt = new HashSet<>();
		// Old School Bonds and basic exempt tools/consumables per OSRS Wiki GE tax exemption list
		exempt.add(ItemID.OLD_SCHOOL_BOND);
		exempt.add(ItemID.CHISEL);
		exempt.add(ItemID.GARDENING_TROWEL);
		exempt.add(ItemID.HAMMER);
		exempt.add(ItemID.NEEDLE);
		exempt.add(ItemID.PESTLE_AND_MORTAR);
		exempt.add(ItemID.RAKE);
		exempt.add(ItemID.SAW);
		exempt.add(ItemID.SECATEURS);
		exempt.add(ItemID.SEED_DIBBER);
		exempt.add(ItemID.SHEARS);
		exempt.add(ItemID.SPADE);
		exempt.add(ItemID.WATERING_CAN);
		// Untradeable Herblore quest/minigame items cannot be taxed on the GE
		exempt.add(ItemID.SERUM_207_4);
		exempt.add(ItemID.SERUM_207_3);
		exempt.add(ItemID.SERUM_207_2);
		exempt.add(ItemID.SERUM_207_1);
		exempt.add(ItemID.MOONLIGHT_POTION4);
		exempt.add(ItemID.MOONLIGHT_POTION3);
		exempt.add(ItemID.MOONLIGHT_POTION2);
		exempt.add(ItemID.MOONLIGHT_POTION1);
		exempt.add(ItemID.MOONLIGHT_GRUB);
		exempt.add(ItemID.MOONLIGHT_GRUB_PASTE);
		exempt.add(ItemID.CRYSTAL_DUST);
		EXEMPT_ITEM_IDS = Collections.unmodifiableSet(exempt);
	}

	private GeTaxRules()
	{
	}

	/**
	 * Returns true if the given item ID is explicitly exempt from Grand Exchange tax.
	 */
	public static boolean isItemTaxExempt(int itemId)
	{
		if (itemId <= 0)
		{
			return true;
		}
		if (EXEMPT_ITEM_IDS.contains(itemId))
		{
			return true;
		}
		return !ItemIdMappings.isTradeable(itemId);
	}

	public static Set<Integer> getExemptItemIds()
	{
		return EXEMPT_ITEM_IDS;
	}
}

package com.herbwise.data;

/**
 * Official Old School RuneScape experience table and level progression helper methods.
 * Uses the exact OSRS experience curve formula without approximation.
 */
public final class HerbloreXpTable
{
	public static final int MIN_LEVEL = 1;
	public static final int MAX_SKILL_LEVEL = 99;
	public static final int MAX_VIRTUAL_LEVEL = 126;
	public static final long MAX_XP = 200_000_000L;

	public static final int[] LEVEL_PRESETS = new int[]{70, 75, 80, 85, 90, 95, 99};

	/**
	 * Exact OSRS XP required for levels 1..99 (index 0 = level 1, index 98 = level 99).
	 */
	private static final long[] XP_FOR_LEVEL = new long[MAX_VIRTUAL_LEVEL + 1];

	static
	{
		XP_FOR_LEVEL[0] = 0L;
		XP_FOR_LEVEL[1] = 0L;
		long points = 0L;
		for (int lvl = 1; lvl < MAX_VIRTUAL_LEVEL; lvl++)
		{
			points += (long) Math.floor(lvl + 300.0 * Math.pow(2.0, lvl / 7.0));
			XP_FOR_LEVEL[lvl + 1] = points / 4L;
		}
	}

	private HerbloreXpTable()
	{
	}

	/**
	 * Returns the exact minimum XP required to reach the specified level (1..126).
	 */
	public static long getXpForLevel(int level)
	{
		if (level <= 1)
		{
			return 0L;
		}
		if (level > MAX_VIRTUAL_LEVEL)
		{
			return XP_FOR_LEVEL[MAX_VIRTUAL_LEVEL];
		}
		return XP_FOR_LEVEL[level];
	}

	/**
	 * Returns the player's standard OSRS skill level (1..99) for a given XP amount.
	 */
	public static int getLevelForXp(long xp)
	{
		if (xp <= 0L)
		{
			return 1;
		}
		for (int level = MAX_SKILL_LEVEL; level >= 1; level--)
		{
			if (xp >= XP_FOR_LEVEL[level])
			{
				return level;
			}
		}
		return 1;
	}

	/**
	 * Returns the virtual level (1..126) for a given XP amount.
	 */
	public static int getVirtualLevelForXp(long xp)
	{
		if (xp <= 0L)
		{
			return 1;
		}
		for (int level = MAX_VIRTUAL_LEVEL; level >= 1; level--)
		{
			if (xp >= XP_FOR_LEVEL[level])
			{
				return level;
			}
		}
		return 1;
	}

	/**
	 * Calculates exact XP needed to reach {@code targetLevel} from {@code currentXp}.
	 * Returns 0 if {@code currentXp} already meets or exceeds {@code targetLevel}.
	 */
	public static long getXpRemainingToLevel(long currentXp, int targetLevel)
	{
		long safeCurrent = Math.max(0L, currentXp);
		long targetXp = getXpForLevel(targetLevel);
		return Math.max(0L, targetXp - safeCurrent);
	}

	/**
	 * Calculates exact XP remaining to reach the next Herblore level (capped at 99).
	 */
	public static long getXpRemainingToNextLevel(long currentXp)
	{
		int currentLevel = getLevelForXp(currentXp);
		if (currentLevel >= MAX_SKILL_LEVEL)
		{
			return 0L;
		}
		return getXpRemainingToLevel(currentXp, currentLevel + 1);
	}

	/**
	 * Calculates the percentage progress (0.0 to 100.0) between the player's current level and next level.
	 */
	public static double getProgressToNextLevelPercent(long currentXp)
	{
		int currentLevel = getLevelForXp(currentXp);
		if (currentLevel >= MAX_SKILL_LEVEL)
		{
			return 100.0;
		}
		long startXp = getXpForLevel(currentLevel);
		long endXp = getXpForLevel(currentLevel + 1);
		long span = endXp - startXp;
		if (span <= 0L)
		{
			return 100.0;
		}
		double progress = ((double) (currentXp - startXp) / (double) span) * 100.0;
		return Math.max(0.0, Math.min(100.0, progress));
	}
}

