package com.herbwise.models;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Historical time-series point and trend analysis summary for the Market Analysis tab.
 */
public class MarketTrendAnalysis
{
	public enum TrendDirection
	{
		RISING("Becoming More Expensive (Rising)", "+"),
		FALLING("Becoming Cheaper (Falling)", ""),
		STABLE("Stable Price Movement", ""),
		INSUFFICIENT_DATA("Insufficient Historical Data", "");

		private final String description;
		private final String prefix;

		TrendDirection(String description, String prefix)
		{
			this.description = description;
			this.prefix = prefix;
		}

		public String getDescription() { return description; }
		public String getPrefix() { return prefix; }
	}

	public static class TimeseriesPoint
	{
		private final long timestampEpochSec;
		private final Long avgHighPrice;
		private final Long avgLowPrice;
		private final int highPriceVolume;
		private final int lowPriceVolume;

		public TimeseriesPoint(
			long timestampEpochSec,
			Long avgHighPrice,
			Long avgLowPrice,
			int highPriceVolume,
			int lowPriceVolume)
		{
			this.timestampEpochSec = timestampEpochSec;
			this.avgHighPrice = avgHighPrice;
			this.avgLowPrice = avgLowPrice;
			this.highPriceVolume = Math.max(0, highPriceVolume);
			this.lowPriceVolume = Math.max(0, lowPriceVolume);
		}

		public long getTimestampEpochSec() { return timestampEpochSec; }
		public Long getAvgHighPrice() { return avgHighPrice; }
		public Long getAvgLowPrice() { return avgLowPrice; }
		public int getHighPriceVolume() { return highPriceVolume; }
		public int getLowPriceVolume() { return lowPriceVolume; }
		public int getTotalVolume() { return highPriceVolume + lowPriceVolume; }

		public long getRepresentativePrice()
		{
			if (avgHighPrice != null && avgHighPrice > 0 && avgLowPrice != null && avgLowPrice > 0)
			{
				return (avgHighPrice + avgLowPrice) / 2L;
			}
			if (avgHighPrice != null && avgHighPrice > 0)
			{
				return avgHighPrice;
			}
			if (avgLowPrice != null && avgLowPrice > 0)
			{
				return avgLowPrice;
			}
			return 0L;
		}
	}

	private final int itemId;
	private final String itemName;
	private final String timestep;
	private final List<TimeseriesPoint> points;
	private final long firstPrice;
	private final long latestPrice;
	private final long minPrice;
	private final long maxPrice;
	private final long averagePrice;
	private final long priceChangeGp;
	private final double priceChangePercent;
	private final double volatilityPercent;
	private final boolean volatileWarning;
	private final TrendDirection direction;
	private final long totalVolumeInWindow;

	public MarketTrendAnalysis(
		int itemId,
		String itemName,
		String timestep,
		List<TimeseriesPoint> points,
		long firstPrice,
		long latestPrice,
		long minPrice,
		long maxPrice,
		long averagePrice,
		long priceChangeGp,
		double priceChangePercent,
		double volatilityPercent,
		boolean volatileWarning,
		TrendDirection direction,
		long totalVolumeInWindow)
	{
		this.itemId = itemId;
		this.itemName = itemName != null ? itemName : ("Item #" + itemId);
		this.timestep = timestep != null ? timestep : "1h";
		this.points = points != null
			? Collections.unmodifiableList(new ArrayList<>(points))
			: Collections.emptyList();
		this.firstPrice = firstPrice;
		this.latestPrice = latestPrice;
		this.minPrice = minPrice;
		this.maxPrice = maxPrice;
		this.averagePrice = averagePrice;
		this.priceChangeGp = priceChangeGp;
		this.priceChangePercent = priceChangePercent;
		this.volatilityPercent = volatilityPercent;
		this.volatileWarning = volatileWarning;
		this.direction = direction != null ? direction : TrendDirection.INSUFFICIENT_DATA;
		this.totalVolumeInWindow = Math.max(0L, totalVolumeInWindow);
	}

	public int getItemId() { return itemId; }
	public String getItemName() { return itemName; }
	public String getTimestep() { return timestep; }
	public List<TimeseriesPoint> getPoints() { return points; }
	public long getFirstPrice() { return firstPrice; }
	public long getLatestPrice() { return latestPrice; }
	public long getMinPrice() { return minPrice; }
	public long getMaxPrice() { return maxPrice; }
	public long getAveragePrice() { return averagePrice; }
	public long getPriceChangeGp() { return priceChangeGp; }
	public double getPriceChangePercent() { return priceChangePercent; }
	public double getVolatilityPercent() { return volatilityPercent; }
	public boolean isVolatileWarning() { return volatileWarning; }
	public TrendDirection getDirection() { return direction; }
	public long getTotalVolumeInWindow() { return totalVolumeInWindow; }
}

package com.herbwise.models;

/**
 * Snapshot of the player's current Herblore skill state retrieved from RuneLite's Client API
 * (or manual override when outside an active game session).
 */
public class PlayerHerbloreData
{
	private final boolean loggedIn;
	private final String playerName;
	private final int currentLevel;
	private final int boostedLevel;
	private final long currentXp;
	private final int nextLevel;
	private final long xpForNextLevel;
	private final long xpRemainingToNextLevel;
	private final double levelProgressPercent;
	private final int unlockablePotionCount;
	private final int totalVerifiedPotionCount;
	private final boolean manualOverride;
	private final int appliedBoostLevels;
	private final String boostSourceDescription;

	public PlayerHerbloreData(
		boolean loggedIn,
		String playerName,
		int currentLevel,
		int boostedLevel,
		long currentXp,
		int nextLevel,
		long xpForNextLevel,
		long xpRemainingToNextLevel,
		double levelProgressPercent,
		int unlockablePotionCount,
		int totalVerifiedPotionCount,
		boolean manualOverride,
		int appliedBoostLevels,
		String boostSourceDescription)
	{
		this.loggedIn = loggedIn;
		this.playerName = playerName != null ? playerName : "Adventurer";
		this.currentLevel = Math.max(1, Math.min(99, currentLevel));
		this.boostedLevel = Math.max(1, boostedLevel);
		this.currentXp = Math.max(0L, currentXp);
		this.nextLevel = Math.max(1, Math.min(99, nextLevel));
		this.xpForNextLevel = Math.max(0L, xpForNextLevel);
		this.xpRemainingToNextLevel = Math.max(0L, xpRemainingToNextLevel);
		this.levelProgressPercent = Math.max(0.0, Math.min(100.0, levelProgressPercent));
		this.unlockablePotionCount = Math.max(0, unlockablePotionCount);
		this.totalVerifiedPotionCount = Math.max(0, totalVerifiedPotionCount);
		this.manualOverride = manualOverride;
		this.appliedBoostLevels = Math.max(0, appliedBoostLevels);
		this.boostSourceDescription = boostSourceDescription != null ? boostSourceDescription : "None";
	}

	public boolean isLoggedIn() { return loggedIn; }
	public String getPlayerName() { return playerName; }
	public int getCurrentLevel() { return currentLevel; }
	public int getBoostedLevel() { return boostedLevel; }
	public long getCurrentXp() { return currentXp; }
	public int getNextLevel() { return nextLevel; }
	public long getXpForNextLevel() { return xpForNextLevel; }
	public long getXpRemainingToNextLevel() { return xpRemainingToNextLevel; }
	public double getLevelProgressPercent() { return levelProgressPercent; }
	public int getUnlockablePotionCount() { return unlockablePotionCount; }
	public int getTotalVerifiedPotionCount() { return totalVerifiedPotionCount; }
	public boolean isManualOverride() { return manualOverride; }
	public int getAppliedBoostLevels() { return appliedBoostLevels; }
	public String getBoostSourceDescription() { return boostSourceDescription; }

	/**
	 * Returns the effective Herblore level including any supported boost (e.g. Botanical pie +4).
	 */
	public int getEffectiveHerbloreLevel()
	{
		return Math.max(currentLevel + appliedBoostLevels, boostedLevel);
	}
}

package com.herbwise.models;

import java.util.Objects;

/**
 * Represents a single required ingredient and quantity in a Herblore recipe.
 */
public class PotionIngredient
{
	private final int itemId;
	private final String name;
	private final int quantity;
	private final boolean tradeable;
	private final String role;

	public PotionIngredient(int itemId, String name, int quantity, boolean tradeable, String role)
	{
		this.itemId = itemId;
		this.name = name != null ? name : "Unknown Item";
		this.quantity = quantity;
		this.tradeable = tradeable;
		this.role = role != null ? role : "Ingredient";
	}

	public PotionIngredient(int itemId, String name, int quantity)
	{
		this(itemId, name, quantity, true, "Ingredient");
	}

	public int getItemId()
	{
		return itemId;
	}

	public String getName()
	{
		return name;
	}

	public int getQuantity()
	{
		return quantity;
	}

	public boolean isTradeable()
	{
		return tradeable;
	}

	public String getRole()
	{
		return role;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o) return true;
		if (!(o instanceof PotionIngredient)) return false;
		PotionIngredient that = (PotionIngredient) o;
		return itemId == that.itemId && quantity == that.quantity && tradeable == that.tradeable
			&& Objects.equals(name, that.name);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(itemId, name, quantity, tradeable);
	}

	@Override
	public String toString()
	{
		return quantity > 1 ? (quantity + "x " + name) : name;
	}
}

