 * XP efficiency metrics, hourly estimates, and market reliability flags.
 */
public class PotionProfitResult
{
	public enum PriceStatus
	{
		PROFITABLE,
		LOSS,
		UNCERTAIN_OR_STALE,
		MISSING_DATA
	}

