		Runnable onBack,
		Consumer<PotionProfitResult> onOpenInBudget,
		Consumer<PotionProfitResult> onOpenInXpCalc,
		Consumer<Integer> onInspectItemMarket)
	{
		this.dataService = dataService;
		this.onBack = onBack;
