		catBadge.setHorizontalAlignment(SwingConstants.RIGHT);
		navRow.add(catBadge, BorderLayout.CENTER);

		contentBox.add(navRow);
		contentBox.add(Box.createRigidArea(new Dimension(0, 6)));

