		heroCard.setLayout(new BorderLayout(8, 4));
		heroCard.setAlignmentX(LEFT_ALIGNMENT);
		heroCard.setBorder(HerbWiseTheme.CARD_BORDER_ACCENT);

		JLabel iconLabel = new JLabel();
